using System;
class DestroyerAccessChecks {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Main(){var ship=NavalShipDefinition.Novik;Check(ship.GunCount==3,"One fore and two aft guns");Check(ship.GunAxisHeight>.42f+.45f,"Raised destroyer gun axis");Check(Math.Abs(ship.GunPosition(1).z-ship.GunPosition(2).z)*ship.Scale>=9.9f,"Two aft mounts leave a real transit gap");Check(NavalGunStationLayout.ShieldHalfWidth-NavalGunStationLayout.ShieldThickness*.5f>.8f+.2f,"Full robot fits between casemate cheeks");Check(.55f+NavalGunStationLayout.RoofY-NavalGunStationLayout.RoofThickness*.5f>2.5f+.2f,"Casemate protects robot height without head collision");foreach(int row in NavalDestroyerAccess.BulkheadRows)Check(NavalDestroyerAccess.OutsideStairs(NavalDestroyerAccess.BulkheadZ(row)),"Bulkhead crosses physical stair volume");Check(!NavalDestroyerAccess.OutsideStairs(NavalDestroyerAccess.BulkheadZ(7)),"Regression: old boundary cut through aft stair");Check(Math.Abs(NavalDestroyerAccess.PumpX)>2.5f,"Pump operator clear of turbine centreline");foreach(int row in NavalDestroyerAccess.BulkheadRows)Check(Math.Abs(NavalDestroyerAccess.PumpZ-NavalDestroyerAccess.BulkheadZ(row))>1.6f,"Pump operator clear of bulkhead");float angle;Check(NavalBattleMath.FiringAngle(450,0,NavalShipDefinition.Novik.ProjectileSpeed,out angle)&&angle<=45,"Destroyer guns cover torpedo approach window");Console.WriteLine("PASS: physical bulkheads outside stair flights, accessible pump and artillery range during approach.");}
}
